  ashadow0 V m -> Forall (pfact_ok V) asan_pure_facts ->
  (forall i, 0 <= i < 2^34 -> m (wa (shad (aspace_beg V) + i)) = Some (Z_to_bv 8 0))
  /\ wr_at asegs m (shad (aspace_beg V)) (2^34).
